import { Code, Code2, Code2Icon, CodeSquare, Cpu, CpuIcon, Database, GitBranch, Handshake, Monitor, Palette, Server, Sparkles, Terminal, Wand2, Zap } from 'lucide-react'
import React, { use } from 'react'

const Skills = ({ data }) => {

   const [userData , setUserData] = React.useState([]);
   const skills = userData[0]?.skills;

   React.useEffect(() => {
     setUserData(data); 

      },[data]);


     const icons = {
        "Frontend" : Monitor,
        "Backend" : Server,
        "AI/ML" : Wand2, 
        "Database" : Database,  
        "Devops" : Cpu,
        "Soft Skills" : Handshake,
        "Others" : Sparkles 
     }
      



  return <div className='mt-12 '>
    <h3>My Skills </h3>
    <div className=' grid grid-cols-3 grid-rows-2 gap-y-8 gap-x-20 mt-8 w-fit mx-auto ' >
        {/* skills  */}

        {
          skills && skills?.map((skill,index)=>{
            const Icon = icons[skill.title]
            return (
        <div  className='flex flex-col p-4   h-72 w-[26rem] border-2 border-text'key={skills.id} >
         
            <h4 className="flex flex-row  gap-2 items-center mx-auto"><Icon/>  {skill.title} </h4>
            <div className='mt-4'>
                  {skill.items && skill.items?.map((item,index)=>{
                    return (
                  <ul className=' flex flex-col gap-2' key={index}>
                    <li> <span> ➤ </span> {item}</li>
                  </ul>
                    )
                  })}
            </div>
         
        </div>
            )
          })
        }
        
    
       
       
    </div>
  </div>
  
}

export default Skills
